class MetaSchemaRegistry:
    def __init__(self):
        # Initialize an empty dictionary to store meta-schemas and vocabularies
        self.registry = {}

    def register_schema(self, name, schema):
        # Register a new meta-schema or vocabulary with its name and schema
        if name in self.registry:
            print(f"Error: Schema '{name}' already exists.")
        else:
            self.registry[name] = schema
            print(f"Schema '{name}' registered successfully.")

    def get_schema(self, name):
