        "address": ip_address,
        "netmask": netmask
    }
    url = f"{base_url}/network/subnets"
    response = requests.post(url, json=data, headers=headers)
    if response.status_code == 201:
        return response.json()
    else:
        raise Exception(f"Failed to create IP subnet: {response.text}")

# Function to update DNS records for an IP address
