import requests

# Define your Coralogix API key and secret
api_key = "your_api_key"
secret = "your_secret"

# Set up the base URL for the Coralogix API
base_url = "https://api.coralogix.com/v2/"

# Create a dictionary of headers including the API key and secret
headers = {
    "Content-Type": "application/json",
    "Authorization": f"Basic {base64.b64encode(f'{api_key}:{secret}'.encode()).decode()}"
}

# Function to create a new trace
def create_trace(trace_name):
    # Prepare the data payload for the trace creation request
    trace_data = {
        "name": trace_name,
        "source_type": "web"
    }

    # Send a POST request to create the trace
    response = requests.post(base_url + "traces", json=trace_data, headers=headers)

    # Check if the request was successful
    if response.status_code == 201:
        return response.json()
    else:
        raise Exception(f"Failed to create trace: {response.text}")

# Function to add data to an existing trace
def add_data_to_trace(trace_id, data):
    # Prepare the data payload for the data addition request
    data_payload = {
        "data": data
    }

    # Send a PUT request to add data to the trace
    response = requests.put(f"{base_url}traces/{trace_id}/data", json=data_payload, headers=headers)

    # Check if the request was successful
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to add data to trace: {response.text}")

# Function to retrieve trace data
def get_trace_data(trace_id):
    # Send a GET request to retrieve data from the trace
    response = requests.get(f"{base_url}traces/{trace_id}", headers=headers)

    # Check if the request was successful
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to retrieve data from trace: {response.text}")
```

