import numpy as np

# Define a class to represent a token in the diffusion process
class Token:
    def __init__(self, id, position):
        self.id = id  # Unique identifier for the token
        self.position = position  # Current position in the diffusion process
        self.previous_position = None  # Previous position of the token (used for merge logic)

# Function to calculate the Euclidean distance between two positions
def euclidean_distance(pos1, pos2):
    return np.linalg.norm(pos1 - pos2)

# Class to represent the token merging algorithm
class TokenMergingAlgorithm:
    def __init__(self):
        self.tokens = []  # List to store tokens
        self.merge_history = {}  # Dictionary to store merge history

    def add_token(self, token_id, initial_position):
        new_token = Token(token_id, initial_position)
        self.tokens.append(new_token)
        self.merge_history[token_id] = set()  # Initialize merge history for each token

    def update_positions(self):
        # Update positions of all tokens based on some rule (e.g., random movement)
        for token in self.tokens:
            token.position += np.random.uniform(-0.1, 0.1) * 10  # Randomly move token within 10 units

    def find_similar_tokens(self, current_token):
        similar_tokens = []
        for token in self.tokens:
            if token.id != current_token.id:
                distance = euclidean_distance(current_token.position, token.position)
                if distance < 5:  # Example threshold for similarity
                    similar_tokens.append((token, distance))
        return similar_tokens

    def merge_tokens(self, token1, token2):
        # Merge the two tokens by setting one to be the previous position of the other
        token1.previous_position = token2.id
        self.merge_history[token1.id].add(token2.id)
        self.merge_history[token2.id].add(token1.id)
        self.tokens.remove(token2)
        self.tokens.remove(token1)
        self.tokens.append(Token(token1.id + 1, token1.position))  # Create a new token with increased ID

    def run_algorithm(self, num_iterations):
        for _ in range(num_iterations):
            self.update_positions()
            for token in self.tokens:
                similar_tokens = self.find_similar_tokens(token)
                if len(similar_tokens) > 1:
                    # Sort similar tokens by distance in ascending order
                    similar_tokens.sort(key=lambda x: x[1])
                    # Merge the closest two tokens
                    self.merge_tokens(*similar_tokens[0])
