class BinaryDataManager:
    def __init__(self):
        # Initialize an empty dictionary to store binary data
        self.data = {}

    def encode_data(self, key, value):
        # Encode the value into a binary format
        encoded_value = value.to_bytes((value.bit_length() + 7) // 8, byteorder='big')
        # Store the encoded value in the dictionary using the key
        self.data[key] = encoded_value

    def decode_data(self, key):
        # Retrieve the encoded value from the dictionary using the key
        encoded_value = self.data.get(key)
        if encoded_value:
            # Decode the binary value back into its original form
            decoded_value = int.from_bytes(encoded_value, byteorder='big')
            return decoded_value
        else:
            return None

    def store_data(self, key, value):
        # Store the original data without any encoding
        self.data[key] = value

    def retrieve_data(self, key):
        # Retrieve the original data stored directly in the dictionary
        return self.data.get(key)

    def iterate_over_data(self):
        # Iterate over all key-value pairs in the dictionary
        for key, value in self.data.items():
            print(f"Key: {key}, Value: {value}")

