    def create_table(self, table_name: str) -> Dict[str, Any]:
        # Create an Ion table using the specified name
        response = self.client.create_table(
            TableName=table_name,
            AttributeDefinitions=[
                {
                    'AttributeName': 'id',
                    'AttributeType': 'N'
                }
            ],
            KeySchema=[
                {
                    'AttributeName': 'id',
                    'KeyType': 'HASH'
                }
            ]
        )
        return response

    def insert_data(self, table_name: str, data: Dict[str, Any]) -> Dict[str, Any]:
        # Insert data into the specified Ion table
        response = self.client.put_item(
            TableName=table_name,
            Item=data
        )
        return response

    def query_data(self, table_name: str, key: int) -> Dict[str, Any]:
        # Query data from the specified Ion table based on a given key
        response = self.client.get_item(
            TableName=table_name,
            Key={
