import pyparsing as pp

# Define the grammar for C-family source files
def c_program():
    """Parse a C-family program."""
    return (
        pp.Forward()  # Start with the forward declaration
        + pp.ZeroOrMore(c_statement)  # Followed by zero or more statements
    )

def c_statement():
    """Parse a statement in a C-family program."""
    return (
        pp.Group(pp.Optional(pp.Keyword("if")) + pp.Group(pp.Word(pp.alphanums)) + "(")
        + pp.Group(pp.OneOrMore(pp.Word(pp.alphanums)))
        + ")"
        | pp.Group(pp.Optional(pp.Keyword("for")) + pp.Group(pp.Word(pp.alphanums)) + "(")
        + pp.Group(pp.ZeroOrMore(pp.Word(pp.alphanums)))
        + ")"
        | pp.Group(pp.Keyword("while")) + pp.Group(pp.Word(pp.alphanums)) + "(")
        + pp.Group(pp.ZeroOrMore(pp.Word(pp.alphanums)))
        + ")"
        | pp.Group(pp.Keyword("return")) + pp.Group(pp.Word(pp.alphanums))
        | pp.Group(pp.Word(pp.alphanums))
    )

# Function to generate AST from parsed program
def generate_ast(parsed_program):
    """Convert the parsed C-program into an AST."""
    ast = {}
    current_node = ast
    for stmt in parsed_program:
        if isinstance(stmt, tuple):  # If it's a compound statement (e.g., if-else)
            sub_ast = {}
            current_node[stmt[0]] = sub_ast
            current_node = sub_ast
            generate_ast(stmt[1])
        else:  # It's a single statement
            current_node[stmt] = None
    return ast

# Example usage
source_code = """
int main() {
    if (x > 0) {
        print(x);
    } else {
        return 0;
    }
}
"""
parsed_program = c_program().parseString(source_code)
ast = generate_ast(parsed_program)
print(ast)

