import numpy as np
from fuzzyset2 import FuzzySet

# Define a class for fuzzy sets
class FuzzySet:
    def __init__(self, membership_function):
        # Initialize the membership function
        self.membership_function = membership_function

    def evaluate(self, value):
        # Evaluate the membership of a given value using the membership function
        return self.membership_function(value)

    def aggregate(self, other_set):
        # Aggregate two fuzzy sets using a sum operation
        return FuzzySet(lambda x: max(self.evaluate(x), other_set.evaluate(x)))

    def intersect(self, other_set):
        # Intersect two fuzzy sets using a minimum operation
        return FuzzySet(lambda x: min(self.evaluate(x), other_set.evaluate(x)))

# Example usage of the FuzzySet class
def linear_membership_function(x):
    # Linear membership function
    if x < 0:
        return 0
    elif x <= 1:
        return x
    else:
        return 1

def triangle_membership_function(x):
    # Triangle membership function
    if x < -1 or x > 2:
        return 0
    elif x <= -1:
        return (x + 1) / 2
    elif x <= 0:
        return 1
    elif x <= 1:
        return (3 - 4 * x) / 2
    else:
        return (2 - x) / 2

# Create fuzzy sets
set_a = FuzzySet(linear_membership_function)
set_b = FuzzySet(triangle_membership_function)

# Perform aggregation and intersection
aggregated_set = set_a.aggregate(set_b)
intersected_set = set_a.intersect(set_b)

# Print results
print("Aggregated Set:", aggregated_set.evaluate(0))
print("Intersected Set:", intersected_set.evaluate(0))

