        # Helper method to traverse the schema
        current_level = self.schema
        for key in path.split('.'):
            if isinstance(current_level, dict) and key in current_level:
                current_level = current_level[key]
            else:
                return None
        return current_level

    def validate_data(self, data):
        # Validate the data against the schema
        errors = []
        for key, value in data.items():
            attribute = self.get_attribute(key)
            if attribute is not None:
                if not isinstance(value, attribute['type']):
                    errors.append(f"Error: Expected {attribute['type']}, got {type(value).__name__} for key '{key}'")
                elif 'format' in attribute and value != attribute['format']:
                    errors.append(f"Error: Invalid format for key '{key}', expected {attribute['format']}")
            else:
                errors.append(f"Error: Key '{key}' not found in schema")
        return errors

    def format_data(self, data):
        # Format the data based on the schema
        formatted_data = {}
        for key, value in data.items():
            attribute = self.get_attribute(key)
            if attribute is not None:
                if 'title' in attribute:
                    formatted_data[attribute['title']] = value
                elif 'description' in attribute:
                    formatted_data[f"{attribute['description']}"] = value
            else:
                formatted_data[key] = value
        return formatted_data

