import jupyter

class NotebookCache:
    def __init__(self):
        # Initialize an empty dictionary to store notebook paths
        self.cache = {}

    def add_notebook(self, notebook_path):
        # Add a new notebook path to the cache
        if notebook_path not in self.cache:
            self.cache[notebook_path] = True
            print(f"Added notebook: {notebook_path}")
        else:
            print(f"Notebook already exists: {notebook_path}")

    def get_notebooks(self):
        # Retrieve all notebook paths from the cache
        return list(self.cache.keys())

    def remove_notebook(self, notebook_path):
        # Remove a notebook path from the cache
        if notebook_path in self.cache:
            del self.cache[notebook_path]
            print(f"Removed notebook: {notebook_path}")
        else:
            print(f"Notebook does not exist: {notebook_path}")

# Example usage
cache = NotebookCache()
cache.add_notebook("path/to/notebook1.ipynb")
cache.add_notebook("path/to/notebook2.ipynb")
print(cache.get_notebooks())  # Output: ['path/to/notebook1.ipynb', 'path/to/notebook2.ipynb']
cache.remove_notebook("path/to/notebook1.ipynb")
print(cache.get_notebooks())  # Output: ['path/to/notebook2.ipynb']
